int checks=0;
void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);++checks;}
void rejected(const std::function<void()>& fn,const std::string& code=""){try{fn();}catch(const Error& e){require(code.empty()||e.code==code,"Native renderer rejected input with incorrect code");return;}throw std::runtime_error("Invalid render unexpectedly accepted");}
using P=std::array<double,3>;
P minus(P a,P b){for(int i=0;i<3;++i)a[i]-=b[i];return a;}P plus(P a,P b){for(int i=0;i<3;++i)a[i]+=b[i];return a;}P times(P a,double s){for(auto& n:a)n*=s;return a;}double dot(P a,P b){return a[0]*b[0]+a[1]*b[1]+a[2]*b[2];}P cross(P a,P b){return {a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]};}
std::array<unsigned char,4> pixel(const RgbaImage& im,int x,int y){const auto i=(static_cast<std::size_t>(y)*im.width+x)*4;return {im.pixels[i],im.pixels[i+1],im.pixels[i+2],im.pixels[i+3]};}
std::size_t ink(const RgbaImage& im){std::size_t out=0;for(std::size_t i=0;i<im.pixels.size();i+=4)if(im.pixels[i]!=255||im.pixels[i+1]!=255||im.pixels[i+2]!=255)++out;return out;}
double center_x(const RgbaImage& im,int channel){double sum=0,n=0;for(std::uint32_t y=0;y<im.height;++y)for(std::uint32_t x=0;x<im.width;++x){const auto c=pixel(im,x,y);if(c[channel]>200&&c[(channel+1)%3]<50&&c[(channel+2)%3]<50){sum+=x+.5;++n;}}require(n>50,"Color centroid has sufficient visible pixels");return sum/n;}
Json settings(){return {{"width",256},{"height",256},{"camera",{{"yaw",0},{"pitch",std::acos(-1.)/2},{"zoom",1},{"pan",{0,0}}}},{"render",{{"lighting",{{"enabled",false}}},{"background",{{"color",{1,1,1}}}},{"grid",false},{"axes",false},{"edges",false},{"floor",{{"enabled",false}}}}},{"appearance",{{"default_color",{1,0,0}},{"parts",Json::array()}}}};}
