 Json lo={1e300,1e300,1e300},hi={-1e300,-1e300,-1e300};auto include=[&](const Json& p){for(int k=0;k<3;++k){lo[k]=std::min(lo[k].get<double>(),p[k].get<double>());hi[k]=std::max(hi[k].get<double>(),p[k].get<double>());}};for(const auto& p:points)include(p);for(const auto& line:curves)for(const auto& p:line.at("points"))include(p);
