struct Hit {double t,u,v;int triangle;};
// Independent source-space Moller-Trumbore camera oracle. It never calls any
// renderer projection, clipping, texture or visibility helper.
Hit oracle(const Json& data,const Json& opts,double x,double y){
 const auto& camera=opts.at("camera");const double yaw=camera.at("yaw"),pitch=camera.at("pitch"),zoom=camera.at("zoom"),cy=std::cos(yaw),sy=std::sin(yaw),cp=std::cos(pitch),sp=std::sin(pitch);const P bx{cy,-sy,0},by{sy*sp,cy*sp,cp},bz{sy*cp,cy*cp,-sp};const auto& bounds=data.at("summary").at("bounds");P center{};double span=0;for(int i=0;i<3;++i){center[i]=(bounds.at("min")[i].get<double>()+bounds.at("max")[i].get<double>())/2;span=std::max(span,bounds.at("max")[i].get<double>()-bounds.at("min")[i].get<double>());}const auto size=std::min(opts.at("width").get<int>(),opts.at("height").get<int>());const auto scale=size*.68*zoom;const auto u=(x-opts.at("width").get<int>()*.5-camera.at("pan")[0].get<double>()*size)/scale,v=(opts.at("height").get<int>()*.5+camera.at("pan")[1].get<double>()*size-y)/scale;const bool perspective=opts.at("render").value("projection",std::string("orthographic"))=="perspective";const double d=3.;const auto origin=perspective?times(bz,-d):plus(plus(times(bx,u),times(by,v)),times(bz,-2));const auto direction=perspective?plus(bz,plus(times(bx,u/d),times(by,v/d))):bz;Hit result{1e300,0,0,-1};const auto& geometry=data.at("artifact_geometry");auto point=[&](int i){P p;for(int k=0;k<3;++k)p[k]=(geometry.at("positions")[i][k].get<double>()-center[k])/span;return p;};for(std::size_t i=0;i<geometry.at("triangles").size();++i){const auto& t=geometry.at("triangles")[i];const auto a=point(t[0]),b=point(t[1]),c=point(t[2]),e1=minus(b,a),e2=minus(c,a),h=cross(direction,e2);const auto det=dot(e1,h);if(std::abs(det)<1e-12)continue;const auto s=minus(origin,a);const auto uu=dot(s,h)/det;const auto q=cross(s,e1);const auto vv=dot(direction,q)/det,tt=dot(e2,q)/det;if(uu>1e-7&&vv>1e-7&&uu+vv<1-1e-7&&tt>0&&tt<result.t)result={tt,uu,vv,static_cast<int>(i)};}return result;
}
